css:
.sticky-widget { position: fixed; right: 2rem; bottom: 2rem; z-index: 90;
  display: flex; flex-direction: column; align-items: center; gap: 0.75rem;
  width: 25rem; padding: 1.75rem 0.75rem 0.75rem;
  border-radius: 1.75rem; background-color: var(--bg-inverse); color: var(--text-inverse); text-align: center;
  opacity: 0; transform: translateY(1.5rem); pointer-events: none;
  transition: opacity 300ms ease, transform 300ms ease; }
.sticky-widget_text { opacity: 0.8; }
@media screen and (max-width: 767px) { .sticky-widget { left: 0px; right: 0px; bottom: 0px; width: auto;
    flex-direction: row; justify-content: space-between; gap: 1rem;
    padding: 0.75rem 1.25rem; border-radius: 1.25rem 1.25rem 0px 0px; text-align: left; } }
@media screen and (max-width: 767px) { .sticky-widget_text { display: none; } }
